// Lê o evento da Evolution, guarda o histórico por contacto e só segue para mensagens novas de clientes
const body = $input.first().json.body || {};
if ((body.event || '').toLowerCase() !== 'messages.upsert') return [];
const d = body.data || {};
const key = d.key || {};
const jid = key.remoteJid || '';
if (!jid || jid.endsWith('@g.us') || jid === 'status@broadcast' || jid.endsWith('@newsletter')) return [];
const m = d.message || {};
const texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) || (m.imageMessage && m.imageMessage.caption) || '';
if (!texto) return [];
const alvo = key.remoteJidAlt || key.senderPn || jid;
const numero = alvo.split('@')[0].split(':')[0];
const MEU_NUMERO = '351967117357'; // número do Tomás que recebe os rascunhos
if (numero === MEU_NUMERO) return [];

const mem = $getWorkflowStaticData('global');
mem.h = mem.h || {};
const h = mem.h[numero] || [];
h.push({ role: key.fromMe ? 'assistant' : 'user', content: texto });
mem.h[numero] = h.slice(-12);
if (key.fromMe) return []; // resposta nossa: só guarda no histórico

// A API do Claude pede alternância user/assistant e começar por user
const msgs = [];
for (const x of mem.h[numero]) {
  if (msgs.length && msgs[msgs.length - 1].role === x.role) msgs[msgs.length - 1].content += '\n' + x.content;
  else msgs.push({ ...x });
}
while (msgs.length && msgs[0].role !== 'user') msgs.shift();

return [{ json: {
  numero, nome: d.pushName || '', texto,
  payload: { model: 'claude-haiku-5-5', max_tokens: 400, system: $('Prompt').first().json.system, messages: msgs }
}}];

const r = $input.first().json;
const c = $('Extrair e memória').first().json;
const bruto = ((r.content || []).find(x => x.type === 'text') || {}).text || '(sem resposta)';
const [parteCliente, partePT = ''] = bruto.split('###PT###');
const pessoa = bruto.includes('[PESSOA]');
const resposta = parteCliente.replace('[PESSOA]', '').trim();
const tCliente = (partePT.match(/Cliente:\s*(.*)/) || [])[1] || '';
const tResposta = (partePT.match(/Resposta:\s*(.*)/) || [])[1] || '';
const texto = (pessoa ? '🙋 PRECISA DE TI\n' : '📝 RASCUNHO\n') +
  `De: ${c.nome} (+${c.numero})\n\n` +
  `Mensagem: ${c.texto}\n` + (tCliente ? `🇵🇹 ${tCliente}\n` : '') +
  `\nResposta proposta:\n${resposta}\n` + (tResposta ? `🇵🇹 ${tResposta}\n` : '') +
  `\nResponder: https://wa.me/${c.numero}`;
return [{ json: { texto } }];
